const records=fs.readFileSync('artifacts/pau-andalucia-resolution/completed-exercises.jsonl','utf8').trim().split(/\r?\n/).map(JSON.parse);
const selected=observations.map(o=>records.find(x=>x.queueIndex===o.queueIndex));
test('839 PDF-bound source inspections; 1553 reversible presentation edits, zero human approvals',()=>{
 let changes=0;
 for(const r of selected){const p=sourceProjection(r);changes+=p.changes.length;assert.equal(p.evidence.humanApproval,false);assert.equal(restoreText(p.text,p.changes),r.sourceLiteral);assert.ok(!hasSourceControls(p.text));}
 assert.equal(selected.length,839);assert.equal(changes,1553);
});
test('all source-bound prompts retain complete source wording and a reversible glyph ledger',()=>{
 for(const r of selected){const p=sourceProjection(r);for(const part of r.parts){const s=p.projectFragment(part.prompt);assert.ok(!hasSourceControls(s.text));assert.equal(restoreText(s.text,s.changes),part.prompt);}}
});
